// TEMPORARY: benchmarks node_modules cache archive formats. Remove before merging.
// Run from the repository root after the node_modules cache was restored and extracted.

import { spawn } from 'child_process';
import fs from 'fs';
import path from 'path';

const root = process.cwd();
const isWindows = process.platform === 'win32';
const work = path.join(root, '.build', 'bench');
fs.rmSync(work, { recursive: true, force: true });
fs.mkdirSync(work, { recursive: true });

function run(command: string, cwd: string): Promise<void> {
	return new Promise((resolve, reject) => {
		const child = spawn(command, { cwd, shell: true, stdio: ['ignore', 'ignore', 'pipe'] });
		let stderr = '';
		child.stderr.on('data', data => { stderr += data; });
		child.on('close', code => code === 0 ? resolve() : reject(new Error(`${command} exited with ${code}: ${stderr.slice(-2000)}`)));
	});
}

async function timed(commands: string[], cwd: string): Promise<number> {
	const start = Date.now();
	await Promise.all(commands.map(command => run(command, cwd)));
	return (Date.now() - start) / 1000;
}

function countEntries(dirs: readonly string[]): number {
	let count = 0;
	const stack = dirs.filter(dir => fs.existsSync(dir));
	while (stack.length) {
		const current = stack.pop()!;
		for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
			if (entry.isDirectory()) {
				stack.push(path.join(current, entry.name));
			} else {
				count++;
			}
		}
	}
	return count;
}

/** Removes the node_modules folders that the archives restore, so that each variant extracts into an empty tree. */
function removeNodeModules(): number {
	const start = Date.now();
	for (const dir of nodeModulesDirs) {
		fs.rmSync(dir, { recursive: true, force: true, maxRetries: 5 });
	}
	return (Date.now() - start) / 1000;
}

const listStart = Date.now();
await run(`node build/azure-pipelines/common/listNodeModules.ts .build/bench/list.txt`, root);
const listSeconds = (Date.now() - listStart) / 1000;
const list = fs.readFileSync(path.join(work, 'list.txt'), 'utf8').split('\n').filter(Boolean);
// Weighs each entry by its size plus a fixed cost per file, as creating a file costs about as much as writing 16 KB.
const weights = list.map(file => {
	try {
		const stat = fs.lstatSync(path.join(root, file));
		return (stat.isFile() ? stat.size : 0) + 16384;
	} catch {
		return 16384;
	}
});
const totalWeight = weights.reduce((a, b) => a + b, 0);
console.log(`listNodeModules: ${list.length} entries in ${listSeconds.toFixed(1)}s`);
// The outermost node_modules folder of each entry.
const nodeModulesDirs = [...new Set(list.map(file => {
	const segments = file.split('/');
	return path.join(root, ...segments.slice(0, segments.indexOf('node_modules') + 1));
}))];

/** Splits the list into contiguous parts of about the same weight, so that each folder mostly stays in one part. */
function split(parts: number): string[][] {
	const result: string[][] = Array.from({ length: parts }, () => []);
	let accumulated = 0;
	list.forEach((file, index) => {
		const part = Math.min(parts - 1, Math.floor(accumulated / (totalWeight / parts)));
		result[part].push(file);
		accumulated += weights[index];
	});
	return result;
}

interface IFormat {
	readonly extension: string;
	archive(listFile: string, archive: string): string;
	extract(archive: string, out: string): string;
}

const sevenZip = (level: number): IFormat => ({
	extension: '7z',
	archive: (listFile, archive) => `7z.exe a "${archive}" -mx${level} "@${listFile}"`,
	extract: (archive, out) => `7z.exe x "${archive}" -o"${out}" -aoa -y`,
});
const windowsTarZstd: IFormat = {
	extension: 'tzst',
	archive: (listFile, archive) => `C:\\Windows\\System32\\tar.exe -cf - -T "${listFile}" | zstd -3 -T0 -q -f -o "${archive}"`,
	extract: (archive, out) => `zstd -d -c -q "${archive}" | C:\\Windows\\System32\\tar.exe -xf - -C "${out}"`,
};
const unixTarZstd: IFormat = {
	extension: 'tzst',
	archive: (listFile, archive) => `tar --use-compress-program='zstd -T0 -3' -cf "${archive}" --files-from "${listFile}"`,
	extract: (archive, out) => `tar --use-compress-program='zstd -d -T0' -xf "${archive}" -C "${out}"`,
};

// The archive that the cache action restored, as the PR jobs extract it today.
const current = isWindows
	? { format: sevenZip(3), archive: path.join(root, '.build/node_modules_cache/cache.7z') }
	: { format: unixTarZstd, archive: path.join(root, '.build/node_modules_cache/node-modules.tzst') };

const results: Record<string, unknown>[] = [];

async function measureExtract(name: string, parts: number, archives: string[], format: IFormat, archiveSeconds?: number) {
	const removeSeconds = removeNodeModules();
	const extractSeconds = await timed(archives.map(archive => format.extract(archive, root)), root);
	const sizeMB = archives.reduce((sum, archive) => sum + fs.statSync(archive).size, 0) / 1024 / 1024;
	const entries = countEntries(nodeModulesDirs);
	const result = { name, parts, extractSeconds, archiveSeconds, sizeMB: Math.round(sizeMB), entries, expectedEntries: list.length, removeSeconds };
	console.log(JSON.stringify(result));
	results.push(result);
}

async function variant(name: string, parts: number, format: IFormat) {
	const dir = path.join(work, name);
	fs.mkdirSync(dir, { recursive: true });
	const lists = split(parts);
	const archives = lists.map((_, index) => path.join(dir, `part-${index}.${format.extension}`));
	lists.forEach((files, index) => fs.writeFileSync(path.join(dir, `list-${index}.txt`), files.join('\n') + '\n'));
	try {
		const archiveSeconds = await timed(lists.map((_, index) => format.archive(path.join(dir, `list-${index}.txt`), archives[index])), root);
		await measureExtract(name, parts, archives, format, archiveSeconds);
	} catch (error) {
		console.log(`${name}: failed: ${error}`);
		results.push({ name, parts, error: String(error).slice(0, 500) });
		// Leaves a complete tree for the next variant to archive.
		removeNodeModules();
		await run(current.format.extract(current.archive, root), root);
	}
	fs.rmSync(dir, { recursive: true, force: true, maxRetries: 5 });
}

await measureExtract('current', 1, [current.archive], current.format);

if (isWindows) {
	for (const parts of [4, 8, 16]) {
		await variant(`7z-mx3-x${parts}`, parts, sevenZip(3));
	}
	await variant('7z-mx0-x8', 8, sevenZip(0));
	await variant('tar-zstd-x1', 1, windowsTarZstd);
	await variant('tar-zstd-x8', 8, windowsTarZstd);
} else {
	for (const parts of [4, 8, 16]) {
		await variant(`tar-zstd-x${parts}`, parts, unixTarZstd);
	}
}

console.log('\n| variant | parts | extract (s) | archive (s) | size (MB) | entries | expected |');
console.log('|---|---|---|---|---|---|---|');
for (const r of results) {
	console.log(`| ${r.name} | ${r.parts} | ${typeof r.extractSeconds === 'number' ? r.extractSeconds.toFixed(1) : r.error ? 'failed' : ''} | ${typeof r.archiveSeconds === 'number' ? r.archiveSeconds.toFixed(1) : ''} | ${r.sizeMB ?? ''} | ${r.entries ?? ''} | ${r.expectedEntries ?? ''} |`);
}
if (process.env.GITHUB_STEP_SUMMARY) {
	fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, [
		`### node_modules cache benchmark (${process.platform}, ${list.length} entries)`,
		'',
		'| variant | parts | extract (s) | archive (s) | size (MB) | entries | expected |',
		'|---|---|---|---|---|---|---|',
		...results.map(r => `| ${r.name} | ${r.parts} | ${typeof r.extractSeconds === 'number' ? r.extractSeconds.toFixed(1) : 'failed'} | ${typeof r.archiveSeconds === 'number' ? r.archiveSeconds.toFixed(1) : ''} | ${r.sizeMB ?? ''} | ${r.entries ?? ''} | ${r.expectedEntries ?? ''} |`),
		'',
	].join('\n'));
}
